def find_most_frequent_two_gram():
    import sys
    input = sys.stdin.read
    data = input().strip().split()

    n = int(data[0])
    s = data[1]

    two_gram_count = {}

    for i in range(n - 1):
        two_gram = s[i:i+2]
        if two_gram in two_gram_count:
            two_gram_count[two_gram] += 1
        else:
            two_gram_count[two_gram] = 1

    # Find the two-gram with the maximum frequency
    most_frequent_two_gram = max(two_gram_count, key=two_gram_count.get)
    print(most_frequent_two_gram)

def find_most_frequent_two_gram(n, s):
    two_grams = {}
    for i in range(n - 1):
        two_gram = s[i:i+2]
        two_grams[two_gram] = two_grams.get(two_gram, 0) + 1

    max_count = 0
    most_frequent = ""
    for two_gram, count in two_grams.items():
        if count > max_count:
            max_count = count
            most_frequent = two_gram

    return most_frequent

